new='''/// The worked split of planning.pi, in the draft about the story `id`:
/// its rewrite, a step for it, and a new story for the other piece, each
/// citing under `spec`.
fn split_example(spec: &str, id: &str) -> String {
    format!(
        "```suspense-story\\ntitle: Close a finished sprint\\nmode: chain\\ntarget: rewrite\\nspec:\\n- {spec}/scope/planning/index.pi#Planning.sprint: when Close sprint shows\\nprompt:\\nClose sprint is offered once every story of the current sprint has\\nended, as {spec}/scope/planning/index.pi#Planning.sprint says.\\n```\\n\\n```suspense-story\\ntitle: Say why Close sprint is disabled\\nmode: code\\ntarget: {id}\\nspec:\\n- {spec}/scope/planning/index.pi#Planning.sprint: when Close sprint shows\\nprompt:\\nWhile a story of the current sprint is still going, Close sprint's\\ntooltip says which, as {spec}/scope/planning/index.pi#Planning.sprint says.\\n```\\n\\n```suspense-story\\ntitle: Archive closed sprints\\nmode: chain\\ntarget: new\\nspec:\\n- No match: archiving a closed sprint\\nprompt:\\nA closed sprint is archived with its stories. The spec has nothing on\\narchiving sprints yet, so this is new.\\n```"
    )
}

/// How a proposal is grounded in the spec, as planning.pi says'''
assert old in s; s=s.replace(old,new,1)
old="""    request.push_str(&format!(
        "{}\\n\\n{}\\n\\n{}:\\n{wanted}",
        planning::REPLY,
        story_example(spec),
        planning::WANTED
    ));
    request
}"""
new="""    request.push_str(&format!("{}\\n\\n{}\\n\\n", planning::REPLY, story_example(spec)));
    if let Some(story) = about {
        request.push_str(&format!(
            "{}\\n\\n{}\\n\\n",
            planning::SPLIT_EXAMPLE,
            split_example(spec, &story.name)
        ));
    }
    request.push_str(&format!("{}:\\n{wanted}", planning::WANTED));
    request
}"""
assert old in s; s=s.replace(old,new,1)
open(p,'w').write(s)
EOF
grep -n 'split_story' src/planning.rs | head -3
